@startuml

class Researcher {
  + name : string
  + surname : string
  + RGID : int
  + currentWP : WorkPackage
}

class ResearchGroup {
  + RGID : int
  + leader : Researcher
}

class Department {
  + deptID : int
}

class WorkPackage {
  + WPID : int
  + RGID : int
  + leader : Researcher
}

Researcher "1" -- "0..*" WorkPackage : worksOn

WorkPackage "1" -- "1" ResearchGroup : ledBy

Researcher "1" -- "1" ResearchGroup : belongsTo

Department "1" *-- "1..*" ResearchGroup : contains

@enduml

